// Işığa duyarlı akıllı lamba: ortam karanlıksa LED yanar
const int LDR_PIN = A0;   // 5V - LDR - A0 - 10k - GND
const int LED = 9;
const int ESIK = 400;     // bu değerin altı "karanlık" (kendi ortamına göre ayarla)

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int isik = analogRead(LDR_PIN);   // 0 (karanlık) ... 1023 (çok aydınlık)

  if (isik < ESIK) {
    digitalWrite(LED, HIGH);
  } else {
    digitalWrite(LED, LOW);
  }

  Serial.println(isik);   // Seri Çizici'de değeri izleyip ESIK'i ayarla
  delay(100);
}
